class StudioButton:Button {
 public string Glyph="";public bool Primary,Active;bool hover;
 public StudioButton(){FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;BackColor=Color.White;ForeColor=Color.FromArgb(54,61,78);Cursor=Cursors.Hand;Font=new Font("Segoe UI",10);Height=40;AutoSize=false;Padding=Padding.Empty;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
 protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
 internal static GraphicsPath Rounded(RectangleF r,float radius){var p=new GraphicsPath();float d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent==null?Color.White:Parent.BackColor);var color=Primary?Color.FromArgb(107,77,235):Active?StudioTheme.Active:hover?StudioTheme.Hover:BackColor;using(var path=Rounded(new RectangleF(1,1,Width-3,Height-3),9))using(var b=new SolidBrush(color))g.FillPath(b,path);Color ink=!Enabled?Color.FromArgb(170,174,187):Primary?Color.White:Active?StudioTheme.AccentText:ForeColor;
 if(Glyph.Length>0){DrawIcon(g,Glyph,new Rectangle(12,(Height-20)/2,20,20),ink);TextRenderer.DrawText(g,Text,Font,new Rectangle(40,0,Width-44,Height),ink,TextFormatFlags.VerticalCenter|TextFormatFlags.Left|TextFormatFlags.EndEllipsis);}else TextRenderer.DrawText(g,Text,Font,ClientRectangle,ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);
 if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,new Rectangle(4,4,Width-9,Height-9));}
 internal static void DrawIcon(Graphics g,string name,Rectangle bounds,Color color){var state=g.Save();g.TranslateTransform(bounds.X,bounds.Y);g.ScaleTransform(bounds.Width/24f,bounds.Height/24f);using(var p=new Pen(color,1.8f)){p.StartCap=p.EndCap=LineCap.Round;p.LineJoin=LineJoin.Round;
 switch(name){
 case "Sélection":g.DrawPolygon(p,new PointF[]{new PointF(5,3),new PointF(18,12),new PointF(12,13),new PointF(9,19)});break;
 case "Flèche":g.DrawLine(p,4,19,19,4);g.DrawLines(p,new PointF[]{new PointF(10,4),new PointF(19,4),new PointF(19,13)});break;
 case "Loupe":g.DrawEllipse(p,3,3,13,13);g.DrawLine(p,15,15,21,21);g.DrawLine(p,7,9.5f,12,9.5f);g.DrawLine(p,9.5f,7,9.5f,12);break;
 case "Numéro":g.DrawEllipse(p,2,2,20,20);using(var f=new Font("Segoe UI",12,FontStyle.Bold))using(var b=new SolidBrush(color))g.DrawString("1",f,b,6,1);break;
 case "Texte":g.DrawLine(p,4,4,20,4);g.DrawLine(p,12,4,12,21);g.DrawLine(p,8,21,16,21);break;
 case "Flou local":for(int x=4;x<22;x+=5)for(int y=4;y<22;y+=5)g.DrawEllipse(p,x,y,1.5f,1.5f);break;
 case "Masquer":g.DrawRectangle(p,3,6,18,12);for(int x=6;x<20;x+=4)g.DrawLine(p,x,8,x,16);break;
 case "Surligneur":g.DrawPolygon(p,new PointF[]{new PointF(5,16),new PointF(13,3),new PointF(20,8),new PointF(12,20)});g.DrawLine(p,3,22,20,22);break;
 case "Zone nette":g.DrawEllipse(p,3,3,18,18);g.DrawLine(p,7,12,17,12);g.DrawLine(p,12,7,12,17);break;
 case "Recadrer":g.DrawLines(p,new Point[]{new Point(7,2),new Point(7,17),new Point(22,17)});g.DrawLines(p,new Point[]{new Point(2,7),new Point(17,7),new Point(17,22)});break;
 case "Capturer":g.DrawRectangle(p,3,6,18,14);g.DrawEllipse(p,8,9,8,8);g.DrawLine(p,8,3,16,3);break;
 case "Exporter":g.DrawLine(p,12,2,12,15);g.DrawLines(p,new Point[]{new Point(7,10),new Point(12,15),new Point(17,10)});g.DrawLines(p,new Point[]{new Point(4,16),new Point(4,21),new Point(20,21),new Point(20,16)});break;
 case "Annuler":g.DrawArc(p,5,6,15,14,210,230);g.DrawLines(p,new Point[]{new Point(4,4),new Point(4,10),new Point(10,10)});break;
 case "Rétablir":g.DrawArc(p,3,6,15,14,100,230);g.DrawLines(p,new Point[]{new Point(20,4),new Point(20,10),new Point(14,10)});break;
 default:g.DrawRectangle(p,5,4,14,16);g.DrawLine(p,8,8,16,8);g.DrawLine(p,8,12,16,12);break;
 }}g.Restore(state);}
}
class StudioCard:FlowLayoutPanel {
 public StudioCard(){FlowDirection=FlowDirection.TopDown;WrapContents=false;AutoSize=true;AutoSizeMode=AutoSizeMode.GrowAndShrink;BackColor=Color.White;Padding=new Padding(16);Margin=new Padding(0,0,0,14);Width=258;}
 protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;e.Graphics.Clear(Parent==null?Color.FromArgb(244,245,249):Parent.BackColor);using(var path=StudioButton.Rounded(new RectangleF(0,0,Width-1,Height-1),12))using(var brush=new SolidBrush(StudioTheme.Surface))e.Graphics.FillPath(brush,path);}
}
class ValueSlider:Control {
 readonly NumericUpDown source;bool down;public string Unit="";
 public ValueSlider(NumericUpDown value){source=value;Size=new Size(220,48);TabStop=true;Cursor=Cursors.Hand;SetStyle(ControlStyles.Selectable|ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);source.ValueChanged+=delegate{Invalidate();};source.EnabledChanged+=delegate{Enabled=source.Enabled;};AccessibleRole=AccessibleRole.Slider;}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;float t=(float)((source.Value-source.Minimum)/(source.Maximum-source.Minimum));float y=33,x=10+t*(Width-20);using(var p=new Pen(StudioTheme.Track,4)){p.StartCap=p.EndCap=LineCap.Round;g.DrawLine(p,10,y,Width-10,y);}using(var p=new Pen(Enabled?Color.FromArgb(115,87,240):Color.LightGray,4))g.DrawLine(p,10,y,x,y);using(var b=new SolidBrush(Enabled?Color.FromArgb(115,87,240):Color.LightGray))g.FillEllipse(b,x-6,y-6,12,12);string text=Unit=="×"?"×"+source.Value.ToString("0.0"):source.Value.ToString(source.DecimalPlaces>0?"0.0":"0")+" "+Unit;TextRenderer.DrawText(g,text,Font,new Rectangle(0,0,Width,23),ForeColor,TextFormatFlags.Right);if(Focused)ControlPaint.DrawFocusRectangle(g,new Rectangle(1,1,Width-3,Height-3));}
 void SetFromX(int x){decimal ratio=(decimal)Math.Max(0,Math.Min(1,(x-10f)/(Width-20)));decimal steps=Math.Round(ratio*(source.Maximum-source.Minimum)/source.Increment);source.Value=Math.Max(source.Minimum,Math.Min(source.Maximum,source.Minimum+steps*source.Increment));}
 protected override void OnMouseDown(MouseEventArgs e){if(e.Button==MouseButtons.Left){Focus();down=true;Capture=true;SetFromX(e.X);}}protected override void OnMouseMove(MouseEventArgs e){if(down)SetFromX(e.X);}protected override void OnMouseUp(MouseEventArgs e){down=false;Capture=false;}
 protected override bool IsInputKey(Keys key){return key==Keys.Left||key==Keys.Right||base.IsInputKey(key);}protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right){source.Value=Math.Max(source.Minimum,Math.Min(source.Maximum,source.Value+(e.KeyCode==Keys.Right?source.Increment:-source.Increment)));e.Handled=true;}base.OnKeyDown(e);}
}
